const SHEETS_API = 'https://sheets.googleapis.com/v4/spreadsheets/';
const RANGE = 'Leads!A:I';
const STAGES = {
  talking: 'Em conversa',
  qualified: 'Qualificado',
  not_qualified: 'Não qualificado',
  scheduled: 'Agendado',
  with_team: 'Com a equipe',
  urgent: 'Urgência',
  stopped: 'Pediu para parar',
};
const CHANNELS = { whatsapp: 'WhatsApp' };

// "dd/mm/aaaa hh:mm" no fuso do cliente.
function localDateTime(iso, timeZone) {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('pt-BR', {
      timeZone,
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
    })
      .formatToParts(new Date(iso))
      .map((part) => [part.type, part.value]),
  );
  return `${parts.day}/${parts.month}/${parts.year} ${parts.hour}:${parts.minute}`;
}

function prepare(input) {
  const { lead, timezone } = input;
  const spreadsheetId = input.crm.settings.spreadsheetId;
  const appointment = lead.appointment;
  const service = appointment?.service ? ` (${appointment.service})` : '';
  return {
    spreadsheetId,
    readUrl: `${SHEETS_API}${encodeURIComponent(spreadsheetId)}/values/${encodeURIComponent(RANGE)}`,
    leadId: lead.id,
    phone: lead.phone,
    row: [
      lead.name ?? '',
      lead.phone ?? '',
      STAGES[lead.stage] ?? lead.stage,
      lead.answers.map((item) => `${item.question}: ${item.answer}`).join('\n'),
      appointment ? `${localDateTime(appointment.start, timezone)}${service}` : '',
      CHANNELS[lead.channel] ?? lead.channel,
      localDateTime(lead.firstContactAt, timezone),
      localDateTime(lead.lastContactAt, timezone),
      lead.id,
    ],
  };
}

return $input.all().map((item) => ({ json: prepare(item.json) }));

const SHEETS_API = 'https://sheets.googleapis.com/v4/spreadsheets/';
const HEADER = ['Nome', 'Telefone', 'Etapa', 'Respostas', 'Agendamento', 'Canal', 'Primeiro contato', 'Último contato', 'ID do lead'];
const PHONE_COLUMN = 1;
const ID_COLUMN = 8;

function succeeded(response) {
  return response.error === undefined && response.statusCode >= 200 && response.statusCode < 300;
}

function cell(row, column) {
  return String(Array.isArray(row) ? (row[column] ?? '') : '').trim();
}

function findRow(rows, start, column, value) {
  for (let index = start; index < rows.length; index++) {
    if (cell(rows[index], column) === value) return index;
  }
  return -1;
}

function valuesUrl(prepared) {
  return `${SHEETS_API}${encodeURIComponent(prepared.spreadsheetId)}/values/`;
}

function append(prepared, values) {
  return {
    write: true,
    method: 'POST',
    url: `${valuesUrl(prepared)}${encodeURIComponent('Leads!A:I')}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`,
    body: { majorDimension: 'ROWS', values },
  };
}

function update(prepared, index) {
  const range = `Leads!A${index + 1}:I${index + 1}`;
  return {
    write: true,
    method: 'PUT',
    url: `${valuesUrl(prepared)}${encodeURIComponent(range)}?valueInputOption=RAW`,
    body: { range, majorDimension: 'ROWS', values: [prepared.row] },
  };
}

// Procura pelo ID do lead; sem ele, pelo telefone (o BSUID muda quando o lead troca de número).
function plan(response, prepared) {
  if (!succeeded(response)) return { write: false, response };
  const rows = Array.isArray(response.body?.values) ? response.body.values : [];
  if (rows.length === 0) return append(prepared, [HEADER, prepared.row]);
  const start = HEADER.every((value, column) => cell(rows[0], column) === value) ? 1 : 0;
  let index = findRow(rows, start, ID_COLUMN, prepared.leadId);
  if (index === -1 && prepared.phone !== null) index = findRow(rows, start, PHONE_COLUMN, prepared.phone);
  return index === -1 ? append(prepared, [prepared.row]) : update(prepared, index);
}

return $input.all().map((item, index) => ({
  json: plan(item.json, $('Prepare row').itemMatching(index).json),
}));

function failure(code, retryable) {
  return { ok: false, error: { code, retryable } };
}

function outcome(response) {
  if (response.error !== undefined) {
    // Falha antes da resposta: credencial recusada pelo Google ou problema de rede.
    const message = typeof response.error === 'string' ? response.error : JSON.stringify(response.error ?? '');
    return /invalid_grant|invalid_client|unauthorized_client|invalid_scope|private key|privateKey|asymmetric|PEM|JWT/i.test(message)
      ? failure('auth', false)
      : failure('unavailable', true);
  }
  const status = response.statusCode;
  const message = String(response.body?.error?.message ?? '');
  if (status >= 200 && status < 300) return { ok: true };
  if (status === 401) return failure('auth', false);
  if (status === 403) return failure('forbidden', false);
  if (status === 404 || (status === 400 && /Unable to parse range/i.test(message))) return failure('not_found', false);
  if (status === 429) return failure('rate_limited', true);
  if (status >= 500) return failure('unavailable', true);
  return failure('provider_error', false);
}

return $input.all().map((item) => ({
  json: outcome(item.json.write === false ? item.json.response : item.json),
}));
